<?php
require_once __DIR__.'/db.php'; require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/audit.php'; requireAdmin();
function countRows(mysqli $c,string $t):int { if(!in_array($t,['users','students','events','registrations'],true))return 0; return (int)$c->query("SELECT COUNT(*) total FROM `$t`")->fetch_assoc()['total'];}
$counts=['Users'=>countRows($conn,'users'),'Students'=>countRows($conn,'students'),'Events'=>countRows($conn,'events'),'Registrations'=>countRows($conn,'registrations')];
$latest=$conn->query('SELECT full_name,email,role,status,created_at FROM users ORDER BY created_at DESC,id DESC LIMIT 5')->fetch_all(MYSQLI_ASSOC);
$months=$conn->query("SELECT DATE_FORMAT(registered_at,'%b %Y') month_label,DATE_FORMAT(registered_at,'%Y-%m') month_key,COUNT(*) total FROM registrations WHERE registered_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY month_key,month_label ORDER BY month_key")->fetch_all(MYSQLI_ASSOC);
$logs=$conn->query('SELECT a.action,a.entity_type,a.details,a.created_at,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.id DESC LIMIT 6')->fetch_all(MYSQLI_ASSOC);
logAudit($conn,(int)$_SESSION['user_id'],'VIEW_DASHBOARD','dashboard',null,'Admin opened dashboard');
?>
