><div class="metric-top"><span class="metric-icon"><?=e(substr($label,0,1))?></span><span class="metric-trend">Live data</span></div><p>Total <?=e(strtolower($label))?></p><h2><?=number_format($value)?></h2><small>Loaded from MySQL</small></article><?php endforeach;?></section><section class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2>Registration activity</h2><p>Monthly registrations · recent 6 months</p></div></div><div class="chart-wrap"><canvas id="registrationChart"></canvas><div id="chartFallback" class="hidden">Chart library unavailable.</div></div><script type="application/json" id="chartData"><?=json_encode($months,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?></script></article><article class="panel"><div class="panel-head"><div><h2>Latest registrations</h2><p>Recently created user accounts</p></div><a class="text-link" href="users.php">View all ↗</a></div><div class="user-table-wrap"><table><thead><tr><th>USER</th><th>ROLE</th><th>STATUS</th></tr></thead><tbody><?php foreach($latest as $u):?><tr><td><strong><?=e($u['full_name'])?></strong><small class="table-sub"><?=e($u['email'])?></small></td><td><span class="role-tag"><?=e(ucfirst($u['role']))?></span></td><td><span class="status-tag <?=e($u['status'])?>"><?=e(ucfirst($u['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></article></section><section class="panel"><div class="panel-head"><div><h2>Recent admin activity</h2><p>Latest actions in the audit trail</p></div><a class="text-link" href="audit-logs.php">View audit log ↗</a></div><?php foreach($logs as $l):?><div class="activity-row"><span class="activity-dot"></span><div class="activity-copy"><strong><?=e($l['action'])?> · <?=e($l['entity_type'])?></strong><small><?=e($l['details']?:'Action recorded')?> — <?=e($l['full_name']?:'Deleted user')?></small></div><time><?=e(date('d M, H:i',strtotime($l['created_at'])))?></time></div><?php endforeach;?></section><footer class="app-footer">AdminOS • Role-based administration • Activity is audited</footer></div></main></div></body></html>
